"""Fixed vendor log parser."""

import csv
import sys


def summarize(path: str) -> dict[str, int]:
    counts = {"ok": 0, "malformed": 0, "high": 0}
    with open(path, newline="", encoding="utf-8") as handle:
        for row in csv.DictReader(handle):
            # Fix Bug 1: Check if temperature field exists and is not empty
            temperature_str = row.get("temperature_c", "")
            if not temperature_str:
                counts["malformed"] += 1
                continue

            try:
                temperature = float(temperature_str)
            except ValueError:
                counts["malformed"] += 1
                continue

            # Fix Bug 2: Vendor spec says 350.0 is inclusive upper limit (OK)
            # Temperature > 350.0 is high, <= 350.0 is OK
            if temperature > 350.0:
                counts["high"] += 1
            else:
                counts["ok"] += 1
    return counts


if __name__ == "__main__":
    print(summarize(sys.argv[1]))
